void far win_MakeGroupSelected(int objectNumber, int group)
{
    int window;
    int i;
    struct WinBucket far *bucket;

    win_LockWin(objectNumber);
    window = objectNumber & 0xff00;
    i = 0;
    bucket = win_handles[objectNumber >> 8];
    while (i < bucket->count) {
        if (bucket->objects[i]->group == (unsigned char)group)
            win_SetObjSelectedStateI(window + i, 1);
        i++;
    }
    win_UnlockWin(objectNumber);
}
void far win_MakeGroupSelected(int objectNumber, int group)
{
    int window;
    int i;
    struct WinBucket far *bucket;

    win_LockWin(objectNumber);
    window = objectNumber & 0xff00;
    i = 0;
    bucket = win_handles[objectNumber >> 8];
    for (; i < bucket->count; i++) {
        if (bucket->objects[i]->group == (unsigned char)group)
            win_SetObjSelectedStateI(window + i, 1);
    }
    win_UnlockWin(objectNumber);
}
void far win_MakeGroupSelected(int objectNumber, int group)
{
    struct WinObject far * far *entry;
    int window;
    int i;
    struct WinBucket far *bucket;

    win_LockWin(objectNumber);
    window = objectNumber & 0xff00;
    i = 0;
    bucket = win_handles[objectNumber >> 8];
    if (bucket->count > 0) {
        entry = bucket->objects;
        do {
            if ((*entry)->group == (unsigned char)group)
                win_SetObjSelectedStateI(window + i, 1);
            entry++;
            i++;
        } while (i < bucket->count);
    }
    win_UnlockWin(objectNumber);
}

